// Batna's Android glue (background oral mode), compiled as a Gradle library module.
//
// You never build this directly: `dx` finds it through the
// `#[manganis::ffi("../../android")]` marker in crates/app/src/platform/background.rs,
// copies this folder into its generated Gradle project as `:plugins:plugin`, adds it as a
// dependency of the app and lets the Android manifest merger pull in our service.
// The root project generated by dx supplies the AGP and Kotlin plugin versions, so the
// plugins below carry no versions on purpose.
//
// Adapted from kabar-app main: android/build.gradle.kts (no ML Kit, no dependencies).

plugins {
    id("com.android.library")
    id("org.jetbrains.kotlin.android")
}

android {
    namespace = "app.batna.bridge"
    compileSdk = 34

    defaultConfig {
        minSdk = 28
        // R8 must keep the classes Rust looks up by name over JNI.
        consumerProguardFiles("consumer-rules.pro")
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    kotlinOptions {
        jvmTarget = "17"
    }

    sourceSets {
        getByName("main") {
            java.srcDirs("src/main/kotlin")
        }
    }
}
